/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field CashDiscBaseDays.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableCashDiscBaseDays extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

