public str getName()
{
    return fieldPName(SalesTable, CashDiscBaseDays);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Integer);
    SalesTable salesTable;
    while select CashDiscBaseDays from salesTable
        group by CashDiscBaseDays
    {
        ret.add(salesTable.CashDiscBaseDays);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, CashDiscBaseDays));
    qbr.value(queryValue(_value));
}
